<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;class StoreCommitteeCommitmentRequest extends FormRequest{public function authorize():bool{return$this->user()?->can('comites.compromisos.gestionar')??false;}public function rules():array{return['meeting_id'=>'nullable|exists:committee_meetings,id','agenda_item_id'=>'nullable|exists:committee_agenda_items,id','description'=>'required|string|max:3000','responsible_employee_id'=>'required|exists:empleados,id','due_date'=>'required|date','priority'=>['required',Rule::in(['low','medium','high','critical'])],'notes'=>'nullable|string|max:2000'];}}
